===================================================================
--- src/package-targets.js	
+++ src/package-targets.js	
@@ -0,0 +1,74 @@
+function resolveConditionalTarget(target, conditions) {
+  if (target === null) return null;
+  if (typeof target === 'string') return target;
+  if (Array.isArray(target)) {
+    for (const item of target) {
+      const resolved = resolveConditionalTarget(item, conditions);
+      if (resolved != null) return resolved;
+    }
+    return null;
+  }
+  if (typeof target === 'object') {
+    for (const key of Object.keys(target)) {
+      if (key === 'default' || conditions.includes(key)) {
+        const resolved = resolveConditionalTarget(target[key], conditions);
+        if (resolved != null) return resolved;
+      }
+    }
+    return null;
+  }
+  return null;
+}
+
+function isSubpathMap(map, kind) {
+  const keys = Object.keys(map);
+  if (keys.length === 0) return false;
+  return keys.every((key) =>
+    kind === 'imports' ? key.startsWith('#') : key === '.' || key.startsWith('./'),
+  );
+}
+
+function matchPattern(map, request, conditions, kind) {
+  for (const key of Object.keys(map)) {
+    const star = key.indexOf('*');
+    if (star === -1) continue;
+    const prefix = key.slice(0, star);
+    const suffix = key.slice(star + 1);
+    if (
+      request.length >= prefix.length + suffix.length &&
+      request.startsWith(prefix) &&
+      request.endsWith(suffix)
+    ) {
+      const matched = request.slice(prefix.length, request.length - suffix.length);
+      const target = resolveConditionalTarget(map[key], conditions);
+      if (typeof target === 'string') {
+        return target.split('*').join(matched);
+      }
+    }
+  }
+  return null;
+}
+
+export function resolvePackageMap(map, request, conditions, kind) {
+  if (map == null) return null;
+
+  if (typeof map !== 'object' || Array.isArray(map)) {
+    if (kind === 'exports' && request === '.') {
+      return resolveConditionalTarget(map, conditions);
+    }
+    return null;
+  }
+
+  if (!isSubpathMap(map, kind)) {
+    if (kind === 'exports' && request === '.') {
+      return resolveConditionalTarget(map, conditions);
+    }
+    return null;
+  }
+
+  if (Object.prototype.hasOwnProperty.call(map, request)) {
+    return resolveConditionalTarget(map[request], conditions);
+  }
+
+  return matchPattern(map, request, conditions, kind);
+}

Index: src/resolver.js
===================================================================
--- src/resolver.js	
+++ src/resolver.js	
@@ -0,0 +1,213 @@
+import fs from 'node:fs';
+import path from 'node:path';
+
+import {
+  ModuleNotFoundError,
+  PackageImportNotDefinedError,
+  PackagePathNotExportedError,
+  InvalidModuleSpecifierError,
+} from './errors.js';
+import { resolvePackageMap } from './package-targets.js';
+import {
+  isCoreModule,
+  isDirectory,
+  isFile,
+  isPathInside,
+  nodeModulesPaths,
+  parsePackageSpecifier,
+} from './utils.js';
+
+const DEFAULT_EXTENSIONS = ['.js', '.json', '.node'];
+const DEFAULT_CONDITIONS = ['node', 'require'];
+
+export class Resolver {
+  constructor(options = {}) {
+    this.basedir = path.resolve(options.basedir ?? process.cwd());
+    this.extensions = [...(options.extensions ?? DEFAULT_EXTENSIONS)];
+    this.conditions = [...(options.conditions ?? DEFAULT_CONDITIONS)];
+    this.preserveSymlinks = options.preserveSymlinks ?? false;
+    this.packageCache = new Map();
+  }
+
+  resolve(request, basedir = this.basedir) {
+    if (typeof request !== 'string' || request.length === 0) {
+      throw new TypeError('The "request" argument must be a non-empty string');
+    }
+
+    if (request.startsWith('node:') || isCoreModule(request)) {
+      return request;
+    }
+
+    const start = path.resolve(basedir);
+    let resolved;
+
+    if (request.startsWith('#')) {
+      resolved = this.#resolvePackageImport(request, start);
+    } else if (path.isAbsolute(request)) {
+      resolved = this.#loadAsFileOrDirectory(request);
+    } else if (
+      request === '.' ||
+      request === '..' ||
+      request.startsWith('./') ||
+      request.startsWith('../')
+    ) {
+      resolved = this.#loadAsFileOrDirectory(path.resolve(start, request));
+    } else {
+      resolved = this.#loadNodeModules(request, start);
+    }
+
+    if (!resolved) {
+      throw new ModuleNotFoundError(request, nodeModulesPaths(start));
+    }
+    return this.#finalize(resolved);
+  }
+
+  readPackageJson(packagePath) {
+    if (this.packageCache.has(packagePath)) {
+      return this.packageCache.get(packagePath);
+    }
+    let parsed = null;
+    try {
+      const raw = fs.readFileSync(packagePath, 'utf8');
+      parsed = JSON.parse(raw);
+      if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed)) {
+        parsed = null;
+      }
+    } catch (error) {
+      if (error.code !== 'ENOENT' && !(error instanceof SyntaxError)) {
+        throw error;
+      }
+      parsed = null;
+    }
+    this.packageCache.set(packagePath, parsed);
+    return parsed;
+  }
+
+  #finalize(file) {
+    if (this.preserveSymlinks) return file;
+    try {
+      return fs.realpathSync.native(file);
+    } catch {
+      return file;
+    }
+  }
+
+  #loadAsFile(base) {
+    if (isFile(base)) return base;
+    for (const extension of this.extensions) {
+      const candidate = base + extension;
+      if (isFile(candidate)) return candidate;
+    }
+    return null;
+  }
+
+  #loadIndex(directory) {
+    for (const extension of this.extensions) {
+      const candidate = path.join(directory, `index${extension}`);
+      if (isFile(candidate)) return candidate;
+    }
+    return null;
+  }
+
+  #loadAsDirectory(directory) {
+    if (!isDirectory(directory)) return null;
+
+    const packagePath = path.join(directory, 'package.json');
+    if (isFile(packagePath)) {
+      const pkg = this.readPackageJson(packagePath);
+      const main = pkg?.main;
+      if (typeof main === 'string' && main.length > 0) {
+        const mainBase = path.resolve(directory, main);
+        const resolved = this.#loadAsFile(mainBase) ?? this.#loadIndex(mainBase);
+        if (resolved) return resolved;
+      }
+    }
+
+    return this.#loadIndex(directory);
+  }
+
+  #loadAsFileOrDirectory(base) {
+    return this.#loadAsFile(base) ?? this.#loadAsDirectory(base);
+  }
+
+  #loadNodeModules(request, start) {
+    const { packageName, subpath } = parsePackageSpecifier(request);
+    if (!packageName) return null;
+
+    for (const modulesDir of nodeModulesPaths(start)) {
+      const packageDir = path.join(modulesDir, packageName);
+      if (!isDirectory(packageDir)) continue;
+      const resolved = this.#resolvePackageEntry(packageDir, subpath);
+      if (resolved) return resolved;
+    }
+    return null;
+  }
+
+  #resolvePackageEntry(packageDir, subpath) {
+    const packagePath = path.join(packageDir, 'package.json');
+    const pkg = isFile(packagePath) ? this.readPackageJson(packagePath) : null;
+
+    if (pkg && pkg.exports !== undefined) {
+      const request = subpath === '' ? '.' : `./${subpath}`;
+      const target = resolvePackageMap(pkg.exports, request, this.conditions, 'exports');
+      if (target == null) {
+        throw new PackagePathNotExportedError(packagePath, request);
+      }
+      return this.#resolveTarget(packageDir, packagePath, target, request);
+    }
+
+    if (subpath === '') {
+      return this.#loadAsDirectory(packageDir);
+    }
+
+    const base = path.resolve(packageDir, subpath);
+    if (!isPathInside(packageDir, base)) {
+      throw new InvalidModuleSpecifierError(`${packageDir}/${subpath}`);
+    }
+    return this.#loadAsFileOrDirectory(base);
+  }
+
+  #resolveTarget(packageDir, packagePath, target, request) {
+    if (!target.startsWith('./')) {
+      throw new InvalidModuleSpecifierError(request, 'invalid "exports" target');
+    }
+    const targetPath = path.resolve(packageDir, target);
+    if (!isPathInside(packageDir, targetPath)) {
+      throw new InvalidModuleSpecifierError(request, 'target escapes package directory');
+    }
+    const resolved = this.#loadAsFileOrDirectory(targetPath);
+    if (!resolved) {
+      throw new ModuleNotFoundError(request, [packageDir]);
+    }
+    return resolved;
+  }
+
+  #findPackageScope(from) {
+    let directory = path.resolve(from);
+    const { root } = path.parse(directory);
+
+    for (;;) {
+      if (path.basename(directory) === 'node_modules') return null;
+      const candidate = path.join(directory, 'package.json');
+      if (isFile(candidate)) return candidate;
+      if (directory === root) return null;
+      directory = path.dirname(directory);
+    }
+  }
+
+  #resolvePackageImport(request, start) {
+    const packagePath = this.#findPackageScope(start);
+    if (!packagePath) {
+      throw new PackageImportNotDefinedError(request, null);
+    }
+    const pkg = this.readPackageJson(packagePath);
+    if (!pkg || pkg.imports === undefined) {
+      throw new PackageImportNotDefinedError(request, packagePath);
+    }
+    const target = resolvePackageMap(pkg.imports, request, this.conditions, 'imports');
+    if (target == null) {
+      throw new PackageImportNotDefinedError(request, packagePath);
+    }
+    return this.#resolveTarget(path.dirname(packagePath), packagePath, target, request);
+  }
+}

Index: src/utils.js
===================================================================
--- src/utils.js	
+++ src/utils.js	
@@ -0,0 +1,68 @@
+import fs from 'node:fs';
+import path from 'node:path';
+import { builtinModules } from 'node:module';
+
+const CORE_MODULES = new Set();
+for (const name of builtinModules) {
+  CORE_MODULES.add(name);
+  CORE_MODULES.add(`node:${name}`);
+}
+
+export function isCoreModule(specifier) {
+  return CORE_MODULES.has(specifier);
+}
+
+export function isFile(candidate) {
+  try {
+    return fs.statSync(candidate).isFile();
+  } catch {
+    return false;
+  }
+}
+
+export function isDirectory(candidate) {
+  try {
+    return fs.statSync(candidate).isDirectory();
+  } catch {
+    return false;
+  }
+}
+
+export function nodeModulesPaths(start) {
+  const absolute = path.resolve(start);
+  const { root } = path.parse(absolute);
+  const parts = absolute
+    .slice(root.length)
+    .split(path.sep)
+    .filter(Boolean);
+
+  const dirs = [];
+  for (let i = parts.length; i >= 0; i -= 1) {
+    if (parts[i - 1] === 'node_modules') continue;
+    const base = path.join(root, ...parts.slice(0, i));
+    dirs.push(path.join(base, 'node_modules'));
+  }
+  return dirs;
+}
+
+export function parsePackageSpecifier(specifier) {
+  const parts = specifier.split('/');
+  if (specifier.startsWith('@')) {
+    if (parts.length < 2 || !parts[0] || !parts[1]) {
+      return { packageName: null, subpath: '' };
+    }
+    return {
+      packageName: `${parts[0]}/${parts[1]}`,
+      subpath: parts.slice(2).join('/'),
+    };
+  }
+  if (!parts[0]) {
+    return { packageName: null, subpath: '' };
+  }
+  return { packageName: parts[0], subpath: parts.slice(1).join('/') };
+}
+
+export function isPathInside(parent, child) {
+  const relative = path.relative(parent, child);
+  return relative === '' || (!relative.startsWith('..') && !path.isAbsolute(relative));
+}

Index: test/resolver.test.js
===================================================================
--- test/resolver.test.js	
+++ test/resolver.test.js	
@@ -0,0 +1,184 @@
+import { test } from 'node:test';
+import assert from 'node:assert/strict';
+import fs from 'node:fs';
+import os from 'node:os';
+import path from 'node:path';
+
+import {
+  Resolver,
+  resolveSync,
+  PackagePathNotExportedError,
+  PackageImportNotDefinedError,
+} from '../src/index.js';
+
+function writeTree(root, tree) {
+  for (const [relative, contents] of Object.entries(tree)) {
+    const full = path.join(root, relative);
+    fs.mkdirSync(path.dirname(full), { recursive: true });
+    const body =
+      typeof contents === 'string'
+        ? contents
+        : `${JSON.stringify(contents, null, 2)}\n`;
+    fs.writeFileSync(full, body);
+  }
+}
+
+function makeProject(tree) {
+  const root = fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(), 'nmr-')));
+  writeTree(root, tree);
+  return root;
+}
+
+test('returns core module specifiers unchanged', () => {
+  assert.equal(resolveSync('fs'), 'fs');
+  assert.equal(resolveSync('node:path'), 'node:path');
+});
+
+test('resolves relative files, extensions, and directories', () => {
+  const root = makeProject({
+    'src/a.js': '',
+    'src/b/index.js': '',
+    'src/c/package.json': { main: 'lib/entry.js' },
+    'src/c/lib/entry.js': '',
+    'src/d/package.json': { main: '.' },
+    'src/d/index.json': '{}',
+  });
+  const basedir = path.join(root, 'src');
+
+  assert.equal(resolveSync('./a', { basedir }), path.join(root, 'src/a.js'));
+  assert.equal(resolveSync('./a.js', { basedir }), path.join(root, 'src/a.js'));
+  assert.equal(resolveSync('./b', { basedir }), path.join(root, 'src/b/index.js'));
+  assert.equal(resolveSync('./c', { basedir }), path.join(root, 'src/c/lib/entry.js'));
+  assert.equal(resolveSync('./d', { basedir }), path.join(root, 'src/d/index.json'));
+  assert.equal(
+    resolveSync(path.join(root, 'src/a.js'), { basedir }),
+    path.join(root, 'src/a.js'),
+  );
+});
+
+test('walks node_modules, including nested packages and scopes', () => {
+  const root = makeProject({
+    'app/index.js': '',
+    'app/node_modules/left-pad/package.json': { main: 'index.js' },
+    'app/node_modules/left-pad/index.js': '',
+    'app/node_modules/left-pad/extra.js': '',
+    'app/node_modules/bare/index.js': '',
+    'app/node_modules/@scope/pkg/package.json': { main: 'main.js' },
+    'app/node_modules/@scope/pkg/main.js': '',
+    'app/packages/inner/index.js': '',
+    'app/packages/inner/node_modules/left-pad/package.json': { main: 'inner.js' },
+    'app/packages/inner/node_modules/left-pad/inner.js': '',
+  });
+  const app = path.join(root, 'app');
+
+  assert.equal(resolveSync('left-pad', { basedir: app }), path.join(app, 'node_modules/left-pad/index.js'));
+  assert.equal(resolveSync('left-pad/extra', { basedir: app }), path.join(app, 'node_modules/left-pad/extra.js'));
+  assert.equal(resolveSync('bare', { basedir: app }), path.join(app, 'node_modules/bare/index.js'));
+  assert.equal(resolveSync('@scope/pkg', { basedir: app }), path.join(app, 'node_modules/@scope/pkg/main.js'));
+
+  const inner = path.join(app, 'packages/inner');
+  assert.equal(resolveSync('left-pad', { basedir: inner }), path.join(inner, 'node_modules/left-pad/inner.js'));
+  assert.equal(resolveSync('@scope/pkg', { basedir: inner }), path.join(app, 'node_modules/@scope/pkg/main.js'));
+});
+
+test('honors the exports field, conditions, subpaths, and patterns', () => {
+  const root = makeProject({
+    'app/node_modules/pkg/package.json': {
+      exports: {
+        '.': { require: './cjs.js', import: './esm.mjs' },
+        './feature': './feature.js',
+        './pattern/*': './lib/*.js',
+      },
+      main: './legacy.js',
+    },
+    'app/node_modules/pkg/cjs.js': '',
+    'app/node_modules/pkg/esm.mjs': '',
+    'app/node_modules/pkg/feature.js': '',
+    'app/node_modules/pkg/lib/x.js': '',
+    'app/node_modules/pkg/legacy.js': '',
+    'app/node_modules/pkg/secret.js': '',
+  });
+  const app = path.join(root, 'app');
+  const pkg = path.join(app, 'node_modules/pkg');
+
+  assert.equal(resolveSync('pkg', { basedir: app }), path.join(pkg, 'cjs.js'));
+  assert.equal(
+    resolveSync('pkg', { basedir: app, conditions: ['node', 'import'] }),
+    path.join(pkg, 'esm.mjs'),
+  );
+  assert.equal(resolveSync('pkg/feature', { basedir: app }), path.join(pkg, 'feature.js'));
+  assert.equal(resolveSync('pkg/pattern/x', { basedir: app }), path.join(pkg, 'lib/x.js'));
+
+  assert.throws(
+    () => resolveSync('pkg/secret', { basedir: app }),
+    (error) => error instanceof PackagePathNotExportedError && error.code === 'ERR_PACKAGE_PATH_NOT_EXPORTED',
+  );
+});
+
+test('resolves package imports (#specifiers) relative to the package scope', () => {
+  const root = makeProject({
+    'app/package.json': {
+      imports: {
+        '#dep': './src/dep.js',
+        '#cond': { require: './src/cjs.js', default: './src/default.js' },
+      },
+    },
+    'app/src/dep.js': '',
+    'app/src/cjs.js': '',
+    'app/src/default.js': '',
+    'app/src/consumer.js': '',
+  });
+  const basedir = path.join(root, 'app/src');
+
+  assert.equal(resolveSync('#dep', { basedir }), path.join(root, 'app/src/dep.js'));
+  assert.equal(resolveSync('#cond', { basedir }), path.join(root, 'app/src/cjs.js'));
+  assert.equal(
+    resolveSync('#cond', { basedir, conditions: ['import'] }),
+    path.join(root, 'app/src/default.js'),
+  );
+  assert.throws(
+    () => resolveSync('#missing', { basedir }),
+    (error) => error instanceof PackageImportNotDefinedError && error.code === 'ERR_PACKAGE_IMPORT_NOT_DEFINED',
+  );
+});
+
+test('supports custom extension order', () => {
+  const root = makeProject({
+    'src/foo.js': '',
+    'src/foo.ts': '',
+  });
+  const basedir = path.join(root, 'src');
+
+  const tsFirst = new Resolver({ basedir, extensions: ['.ts', '.js'] });
+  assert.equal(tsFirst.resolve('./foo'), path.join(root, 'src/foo.ts'));
+
+  const jsFirst = new Resolver({ basedir, extensions: ['.js', '.ts'] });
+  assert.equal(jsFirst.resolve('./foo'), path.join(root, 'src/foo.js'));
+});
+
