Resolve module specifiers using Node's resolution algorithm.

Options:
  -b, --basedir <dir>  Directory to resolve from (default: cwd)
  -c, --conditions <c> Comma-separated conditions (default: node,require)
  -h, --help           Show this help
`;

function main(argv) {
  let basedir = process.cwd();
  let conditions;
  const requests = [];

  for (let i = 0; i < argv.length; i += 1) {
    const arg = argv[i];
    if (arg === '-h' || arg === '--help') {
      process.stdout.write(HELP);
      return 0;
    }
    if (arg === '-b' || arg === '--basedir') {
      basedir = argv[++i];
      if (!basedir) throw new Error(`Missing value for ${arg}`);
      continue;
    }
    if (arg === '-c' || arg === '--conditions') {
      const value = argv[++i];
      if (!value) throw new Error(`Missing value for ${arg}`);
      conditions = value.split(',').map((item) => item.trim()).filter(Boolean);
      continue;
    }
    requests.push(arg);
  }

  if (requests.length === 0) {
    process.stderr.write(HELP);
    return 1;
  }

  const options = { basedir };
  if (conditions) options.conditions = conditions;

  let failed = false;
  for (const request of requests) {
    try {
      process.stdout.write(`${resolveSync(request, options)}\n`);
    } catch (error) {
      process.stderr.write(`${request}: ${error.message}\n`);
      failed = true;
    }
  }
  return failed ? 1 : 0;
}

try {
  process.exitCode = main(process.argv.slice(2));
} catch (error) {
  process.stderr.write(`${error.message}\n`);
  process.exitCode = 1;
}

