import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { createRequire } from 'node:module';
import { Resolver } from './src/index.js';

const root = fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(), 'nmr-diff-')));
const files = {
  'app/index.js': '',
  'app/node_modules/left-pad/package.json': { main: 'index.js' },
  'app/node_modules/left-pad/index.js': '',
  'app/node_modules/left-pad/extra.json': '{}',
  'app/node_modules/@scope/pkg/package.json': { main: 'main.js' },
  'app/node_modules/@scope/pkg/main.js': '',
  'app/node_modules/bare/index.node': '',
  'app/node_modules/exp/package.json': { exports: { '.': { require: './c.js' }, './f': './f.js', './p/*': './lib/*.js' } },
  'app/node_modules/exp/c.js': '',
  'app/node_modules/exp/f.js': '',
  'app/node_modules/exp/lib/x.js': '',
  'app/packages/inner/node_modules/left-pad/package.json': { main: 'inner.js' },
  'app/packages/inner/node_modules/left-pad/inner.js': '',
  'app/local.js': '',
  'app/dir/index.js': '',
};
for (const [rel, body] of Object.entries(files)) {
  const full = path.join(root, rel);
  fs.mkdirSync(path.dirname(full), { recursive: true });
  fs.writeFileSync(full, typeof body === 'string' ? body : JSON.stringify(body));
}

const app = path.join(root, 'app');
const inner = path.join(app, 'packages/inner');
const cases = [
  [app, 'left-pad'],
  [app, 'left-pad/extra'],
  [inner, 'left-pad'],
  [app, '@scope/pkg'],
  [app, 'bare'],
  [app, 'exp'],
  [app, 'exp/f'],
  [app, 'exp/p/x'],
  [app, './local'],
  [app, './dir'],
  [app, 'fs'],
  [app, 'node:path'],
];

const local = new Resolver({ basedir: app });
let ok = 0;
for (const [basedir, request] of cases) {
  const req = createRequire(path.join(basedir, 'noop.js'));
  let expected;
  try { expected = req.resolve(request); } catch (e) { expected = `ERR:${e.code}`; }
  let actual;
  try { actual = local.resolve(request, basedir); } catch (e) { actual = `ERR:${e.code}`; }
  const match = expected === actual;
  if (match) ok++;
  console.log(`${match ? 'MATCH  ' : 'DIFFER '} ${request.padEnd(14)} node=${expected} ours=${actual}`);
}
console.log(`\n${ok}/${cases.length} match`);
EOF

